3	/** Escapes a string for safe interpolation into HTML text and double-quoted attributes. */
4	export function escapeHtml(value: string): string {
5	  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
6	}
7	
8	function renderLink(link: { title: string; url: string; description?: string }): string {
9	  const description = link.description ? `<p class="link-desc">${escapeHtml(link.description)}</p>` : "";
10	  return `        <li class="link">
11	          <a href="${escapeHtml(link.url)}">${escapeHtml(link.title)}</a>
12	          ${description}
13	        </li>`;
14	}
15	
16	function renderSection(section: Section): string {
17	  const description = section.description ? `      <p class="section-desc">${escapeHtml(section.description)}</p>` : "";
18	  const links = section.links.map(renderLink).join("\n");
19	  return `    <section class="audience">
20	      <h2>${escapeHtml(section.audience)}</h2>
21	${description}
22	      <ul class="links">
23	${links}
24	      </ul>
25	    </section>`;
26	}
